package main

import "testing"

func TestUpperBoundIsTheCap(t *testing.T) {
	delay := BackoffDelay(2, 1, 100, func() float64 { return 1.0 })
	if delay != 4 {
		t.Fatalf("got %v, want 4", delay)
	}
}

func TestLowerBoundIsZero(t *testing.T) {
	delay := BackoffDelay(5, 1, 100, func() float64 { return 0.0 })
	if delay != 0 {
		t.Fatalf("got %v, want 0", delay)
	}
}

func TestDelayNeverExceedsMaxDelayForLargeAttempts(t *testing.T) {
	delay := BackoffDelay(50, 1, 10, func() float64 { return 1.0 })
	if delay != 10 {
		t.Fatalf("got %v, want 10", delay)
	}
}

func TestDefaultRandStaysInBounds(t *testing.T) {
	for attempt := 0; attempt < 10; attempt++ {
		delay := BackoffDelay(attempt, 1, 20, func() float64 { return 0.5 })
		if delay < 0 || delay > 20 {
			t.Fatalf("delay %v out of bounds at attempt %d", delay, attempt)
		}
	}
}

